def P(num,h,fig,tier,grant,inv,title,teaches,figs,status="Expired",**k):
    d=dict(num=num,hash=h,fig=fig,tier=tier,grant=grant,inv=inv,title=title,teaches=teaches,figs=figs,status=status); d.update(k); return d
INTRO = "<p>Growing a calorie crop is half the job. The other half is turning it into food. These patent drawings cover the hand machines that did that work on farms: shelling corn, crushing cane and apples, paring and slicing fruit for drying, grinding grain, and cleaning it with a fanning mill. They run from wood-and-iron machines you can build to adjustable iron burr mills. All are expired and free to copy. The companion guides cover these patents' neighbours in more depth: Gardening for planting tools, Livestock for dairy, and Preservation for drying, canning and cold storage.</p>"
UNPATENTED = ["The quern, the mortar and pestle, the winnowing basket and nixtamalizing corn with wood ash or lime are ancient methods that anyone may use."]
PATENTS = [
P("US4677","c4/19/2a/8103a15a5680c5/US4677.pdf","f5/85/92/f75d7b16991e16/US4677-drawings-page-1.png","A","1846-07-31","Lorenzo B. Glover (Easton, Connecticut)","Corn-sheller",
  "A corn sheller and cleaner worked by hand or other power, made of wood, iron or copper. Two horizontal toothed wheels, the upper one fixed and the lower one turning on a vertical axle, strip the kernels as ears pass between them. The machine also separates corn from cob and chaff in the same pass.","Fig. 1 elevation with the two toothed wheels; other sheets: details"),
P("US19545","56/3e/4d/db7750f5733d3b/US19545.pdf","e3/ef/02/6a870fb452a914/US19545-drawings-page-1.png","A","1858-03-09","Hamilton J. Cox (Warren County, Ohio)","Sugar and cider mill",
  "One roller mill for two jobs: crushing &ldquo;Chinese sugar-cane&rdquo; (sorghum) for syrup and grinding apples. The frame is heavy 6-inch boards, with a driving roller, a third roller behind it, and a guard that stops the crushed cane (bagasse) escaping before its second squeeze. It can be built from timber with turned or iron-shod rollers.","Perspective B; third roller A; guard C"),
P("US29988","01/77/ef/653110f54bb517/US29988.pdf","f5/00/f8/5a0867b1d257d5/US29988-drawings-page-1.png","B","1860-09-11","J. J. Parker (Marietta, Ohio)","Apple parer, corer, and slicer",
  "A crank apple parer with an adjustable knife head and an added slicing knife, so apples come off pared and sliced, ready to dry.","Fig. 1 isometric view; Figs. 2&ndash;3 adjustable head; Fig. 4 main-shaft section"),
P("US19441","42/fe/58/85641febd8dfe4/US19441.pdf","b9/f5/05/16caf82d960622/US19441-drawings-page-1.png","B","1858-02-23","Philander Perry (Troy, New York)","Grain-mill",
  "A portable mill for grinding wheat, corn, oats and peas, and also corn in the ear, by hand or by power. It has a frame, a flywheel, gearing and a shaft carrying eccentric grinding plates.","Fig. 1 perspective of mill and gearing"),
P("US11151","6d/06/d9/e21072af367a51/US11151.pdf","06/eb/da/f4c9a40ae7a462/US11151-drawings-page-1.png","B","1854-06-27","Jesse Bauman (Shepherdstown, Pennsylvania)","Cider-mill",
  "An apple-grinding mill that reduces whole apples to pulp without slicing them first. Bauman notes that pulp is &ldquo;absolutely required&rdquo; to get the most cider from a given quantity of apples. A secondary mill and a press complete it.","Fig. 1 elevation; Fig. 2 grinding plate; Fig. 4 secondary mill"),
P("US198986","72/3a/36/c5436f5af6e455/US198986.pdf","e7/94/b6/3ca62291b1d891/US198986-drawings-page-3.png","B","1878-01-08","Andrew W. Kendrick &amp; Charles T. Kendrick (Brooklyn, New York)","Improvement in grain-separators (fanning-mill)",
  "A fanning mill for separating and cleaning grain and seeds: a fan blast plus shaking screens. The crank is on the operator's side so they can watch and adjust the feed and blast. It shows the shoe, the screens and how they are driven.","Figs. 1&ndash;3: side elevations and longitudinal section"),
P("US636124","ca/be/a9/7566b7b6bbe79f/US636124.pdf","e3/0b/ca/ddd7abd33ba8ba/US636124-drawings-page-1.png","C","1899-10-31","Charles Uncas Farrar (New Orleans, Louisiana)","Coffee or grain mill",
  "A simple, durable hand mill for coffee or grain that can be set to grind coarse or fine. A nut with right- and left-hand threads moves both grinding wheels toward or away from each other at the same time.","Fig. 1 front elevation; sections of the grinding wheels and adjusting nut"),
P("US477","9e/5b/b4/d3a2920cd3c4ad/US477.pdf","18/06/a9/111a8de7adeec9/US477-drawings-page-2.png","C","1837-11-23","Elijah S. Curtis (Boston, Massachusetts)","Construction of mills for grinding corn, grain, &c.",
  "A grist mill with stones, preferably French burrstone, on an improved support for the lower stone. Curtis notes that a small version turned by hand through bevel gears and a crank would be &ldquo;very useful to families&rdquo; for home grinding.","Fig. 1 perspective; Fig. 2 vertical section through stones and support"),
P("US425428","35/98/e5/b27c362de98397/US425428.pdf","c3/e4/d0/e67d0ed94373b1/US425428-drawings-page-1.png","A","1890-04-15","Thomas Holmes","Nut-cracker",
  "A lever nut-cracker for hard wild nuts. A slightly curved cracker arm is pivoted at one end of a base and pressed down by an operating lever, so the nut sits in a roughly triangular opening that closes as you press. The aim, in the patent's words, is enough force to crack the hardest nut without smashing it too much for use. Use it with the foraging calendar's nuts.","Fig. 1 perspective; Fig. 2 side view of the lever and cracker arm"),
P("US39072","4f/56/41/869c49b1b66fa6/US39072.pdf","7d/9e/47/e381e704c07b7e/US39072-drawings-page-1.png","A","1863-06-30","Moses Shelden &amp; Wareham A. Chase","Improvement in spouts for conveying sap",
  "Wooden channels for carrying maple sap downhill to the sugar house, each length gouged out of a single piece of wood. The higher end is left solid and the lower end is thinned to a sharp edge so that each length laps into the next. The line is laid on a row of stakes of different heights, with crotches sawed in their tops, to keep a steady fall over uneven ground.","Fig. 1 two lengths joined; Figs. 2-5 sections of a length"),
P("US20631","e3/1a/3b/a6bc3eb306df4f/US20631.pdf","b1/b0/ae/50994c640f0b15/US20631-drawings-page-1.png","B","1858-06-22","D. M. Cook","Improvement in pans for evaporating cane-juice",
  "A continuous-flow sugar evaporator for cane juice or maple sap. The pan's bottom is crimped from sheet metal into flanges, making a channel that zig-zags across the pan, and wooden headings close the ends. The juice flows along the channel as it boils down, and skimmers sit in alternate bends to take off the scum.","Fig. 1 plan of the zig-zag channel and skimmers"),
P("US240960","eb/b9/c0/06d85b90b07b96/US240960.pdf","f8/77/0d/edf296efa31434/US240960-drawings-page-2.png","C","1881-05-03","John A. A. Buchholz (London)","Roller-mill for grinding grain",
  "A three-roller flour mill. Three cast-iron-framed rollers stand one above the other, so that they work as two pairs. The first pair crushes the grain as it comes in. A sifter takes out the flour from that first crushing and passes the rest of the meal to the second pair. The aim is to free the flour from the bran with simpler machinery. This is the factory version of the hand mills earlier in this appendix.","Fig. 1 side view; Fig. 2 front view; Fig. 3 section through the three rollers; Fig. 4 plan"),
]
